def int_to_roman(number):
    if number < 1 or number > 3999:
        raise ValueError("Input must be between 1 and 3999.")

    # Define the Roman numeral symbols and their corresponding values
    roman_numerals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, numeral in roman_numerals:
        while number >= value:
            result.append(numeral)
            number -= value

    return ''.join(result)

# Example usage
if __name__ == "__main__":
    print(int_to_roman(1))  # Output: "I"
    print(int_to_roman(4))  # Output: "IV"
    print(int_to_roman(9))  # Output: "IX"
    print(int_to_roman(0))  # Output: ""

def run_length_encode(text):
    if not text:
        return ''

    result = []
    count = 1

    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            result.append(str(count) + text[i - 1])
            count = 1

    # Append the last run
    result.append(str(count) + text[-1])

    return ''.join(result)

# Example usage in a browser environment
if __name__ == "__main__":
    input_text = 'aaabcc'
    encoded_text = run_length_encode(input_text)
    print(encoded_text)  # Output: '3a1b2c'

def balanced_brackets(text):
    stack = []
    matching_brackets = {')': '(', '}': '{', ']': '['}

    for char in text:
        if char in matching_brackets.values():
            stack.append(char)
        elif char in matching_brackets.keys():
            if not stack or stack.pop() != matching_brackets[char]:
                return False

    return len(stack) == 0

