def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on the start value
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        last_merged = merged[-1]
        if interval[0] <= last_merged[1]:
            # Merge intervals if they overlap or touch
            merged[-1] = [last_merged[0], max(last_merged[1], interval[1])]
        else:
            # Add non-overlapping interval to the merged list
            merged.append(interval)

    return merged

# Example usage
if __name__ == "__main__":
    input_intervals = [[1, 3], [2, 6], [8, 10]]
    result = merge_intervals(input_intervals)
    print(result)  # Output: [[1, 6], [8, 10]]

def levenshtein(a, b):
    if not a or not b:
        return max(len(a), len(b))

    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]

    for i in range(len(a) + 1):
        dp[i][0] = i
    for j in range(len(b) + 1):
        dp[0][j] = j

    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

    return dp[len(a)][len(b)]

# Example usage
if __name__ == "__main__":
    a = "kitten"
    b = "sitting"
    print(levenshtein(a, b))  # Expected output: 3

    a = ""
    b = "hello"
    print(levenshtein(a, b))  # Expected output: 5

    a = "abc"
    b = "def"
