def parse_duration(text):
    if not text.strip():
        return 0

    try:
        parts = text.split()
        total_seconds = 0

        for part in parts:
            if 'h' in part:
                hours = int(part.replace('h', ''))
                total_seconds += hours * 3600
            elif 'm' in part:
                minutes = int(part.replace('m', ''))
                total_seconds += minutes * 60
            elif 's' in part:
                seconds = int(part.replace('s', ''))
                total_seconds += seconds

        return total_seconds
    except ValueError:
        return None

# Demo
if __name__ == "__main__":
    print(parse_duration('1h30m'))  # Expected Result: 900
    print(parse_duration('45s'))    # Expected Result: 45
    print(parse_duration('2h5s'))   # Expected Result: 1805
    print(parse_duration(''))       # Expected Result: 0
    print(parse_duration('1h30m30')) # Expected Result: None
    print(parse_duration('-1h30m')) # Expected Result: None

def spiral_order(matrix):
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
            print(f"Processing: {matrix[top][i]}")
        top += 1

        # Traverse from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
            print(f"Processing: {matrix[i][right]}")
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
                print(f"Processing: {matrix[bottom][i]}")
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
                print(f"Processing: {matrix[i][left]}")
            left += 1

    return result

# Example usage
if __name__ == "__main__":
    matrix = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    print("Spiral Order:", spiral_order(matrix))

def group_anagrams(words):
    # Create a dictionary to hold groups of anagrams
    anagram_groups = {}

    for word in words:
        # Sort the characters in the word to create a key
        sorted_word = ''.join(sorted(word))

        # If the sorted word is not in the dictionary, add it with the current word as the first element
        if sorted_word not in anagram_groups:
            anagram_groups[sorted_word] = [word]
        else:
            # Otherwise, append the word to the existing group
            anagram_groups[sorted_word].append(word)

    # Convert the dictionary values to a list of lists and return it
    return list(anagram_groups.values())

def main():
    # Example input
    words = ["listen", "silent", "enlist", "google", "gooegl", "elvis"]

    # Group anagrams
    result = group_anagrams(words)

    # Print the result
    print(result)

if __name__ == "__main__":
    main()

def caesar_cipher(text, shift):
    def shift_char(c, shift):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, shift) for c in text)

if __name__ == "__main__":
    # Example usage
    result = caesar_cipher("Hello, World!", 3)
    print(result)  # Output: "Khoor, Zruog!"

def pascal_row(n):
    if n < 0:
        return []

    row = [1]
    for i in range(1, n + 1):
        next_row = [1] * (i + 1)
        for j in range(1, i):
            next_row[j] = row[j - 1] + row[j]
        row = next_row
    return row

# Demo
if __name__ == "__main__":
    print(pascal_row(0))  # Output: [1]
    print(pascal_row(4))  # Output: [1, 4, 6, 4, 1]
    print(pascal_row(5))  # Output: [1, 5, 10, 10, 5, 1]

def longest_common_prefix(words):
    if not words:
        return ''

    # Sort the list of words to ensure the shortest word is first
    words.sort()

    # Compare characters of the first and last words
    for i, char in enumerate(words[0]):
        if char != words[-1][i]:
            return words[0][:i]

    return words[0]

# Example usage
if __name__ == "__main__":
    print(longest_common_prefix(["flower", "flow", "flight"]))  # Expected output: 'fl'
    print(longest_common_prefix(["dog", "racecar", "car"]))      # Expected output: ''
    print(longest_common_prefix([]))                              # Expected output: ''

def binary_search(values, target):
    left, right = 0, len(values) - 1

    while left <= right:
        mid = (left + right) // 2

        if values[mid] == target:
            return mid
        elif values[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

