    # Input: sorted list of integers and target to search for
    values = [1, 2, 3, 4, 5]
    target = 3

    # Output: index of the target or -1 if not present
    result = binary_search(values, target)
    print(result)  # Expected output: 2

def deep_flatten(value):
    def flatten(item):
        if isinstance(item, list):
            return [flatten(i) for i in item]
        else:
            return [item]

    return sum(flatten(value), [])

# Example usage
if __name__ == "__main__":
    print(deep_flatten([1, 2, 3]))  # Output: [1, 2, 3]
    print(deep_flatten([1, 'a', [2, 'b'], 3]))  # Output: [1, 'a', 2, 'b', 3]
    print(deep_flatten([1, [2, [3, 4]], 5]))  # Output: [1, 2, 3, 4, 5]
    print(deep_flatten([]))  # Output: []

def is_valid_ipv4(address):
    # Check if the address is empty
    if not address:
        return False

    # Split the address by dots
    parts = address.split('.')

    # Check if there are exactly four parts
    if len(parts) != 4:
        return False

    # Validate each part
    for part in parts:
        # Check if the part is a digit and not empty
        if not part.isdigit() or not part:
            return False

        # Check if the part is between 0 and 255
        if int(part) < 0 or int(part) > 255:
            return False

        # Check for leading zeros, except for the first part
        if part != '0' and part.startswith('0'):
            return False

    return True

# Example usage in a browser sandbox
if __name__ == "__main__":
    address = "192.168.1.1"
    result = is_valid_ipv4(address)
    print(f"The address '{address}' is valid: {result}")

def word_wrap(text, width):
    if not text:
        return []

    lines = []
    current_line = ""

    for word in text.split():
        if len(current_line) + len(word) + 1 <= width:
            current_line += " " + word
        else:
            lines.append(current_line.strip())
            current_line = word

    if current_line:
        lines.append(current_line.strip())

    return lines

# Demo
if __name__ == "__main__":
    paragraph = "This is a test string that needs to be wrapped"
    width = 10
    wrapped_lines = word_wrap(paragraph, width)
    print(wrapped_lines)

def count_islands(grid):
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '0' or (r, c) in visited:
            return
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(r + dr, c + dc)

    island_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and (r, c) not in visited:
                dfs(r, c)
                island_count += 1

    return island_count

# Example usage
if __name__ == "__main__":
    grid = [
        "101",
        "001",
        "111"
    ]
    print(count_islands(grid))  # Expected output: 3

def next_greater(values):
    if not values:
        return []

    result = [-1] * len(values)
    stack = []

    for i, value in enumerate(values):
        while stack and values[stack[-1]] < value:
            result[stack.pop()] = value
        stack.append(i)

    return result

# Example usage
if __name__ == "__main__":
    input_list = [2, 1, 3]
    output_list = next_greater(input_list)
    print(output_list)  # Output: [3, 3, -1]
